namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public List<int> Ratings { get; set; } = [];

    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1,
                Title = "Classic Margherita Pizza",
                Category = "Italian",
                Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt",
                Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out the dough on a floured surface.\n3. Spread crushed tomatoes evenly over the dough.\n4. Tear mozzarella into pieces and distribute on top.\n5. Bake for 10–12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.",
                Ratings = [5, 4, 5, 4]
            },
            new Recipe
            {
                Id = 2,
                Title = "Spaghetti Carbonara",
                Category = "Italian",
                Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper",
                Steps = "1. Cook spaghetti in salted boiling water until al dente.\n2. Crisp the guanciale in a skillet over medium heat.\n3. Whisk eggs with grated Pecorino and black pepper.\n4. Toss hot pasta with guanciale, then remove from heat.\n5. Stir in the egg mixture quickly, tossing to coat without scrambling.\n6. Serve immediately with extra Pecorino.",
                Ratings = [5, 5, 4]
            },
            new Recipe
            {
                Id = 3,
                Title = "Chicken Tikka Masala",
                Category = "Indian",
                Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion",
                Steps = "1. Marinate chicken in yogurt, garam masala, turmeric, and cumin for at least 1 hour.\n2. Grill or broil chicken until charred.\n3. Sauté onion, garlic, and ginger in a pan.\n4. Add canned tomatoes and simmer for 15 minutes.\n5. Stir in cream and add the cooked chicken.\n6. Simmer for 10 minutes and serve with rice or naan.",
                Ratings = [5, 4, 5, 5]
            },
            new Recipe
            {
                Id = 4,
                Title = "Vegetable Pad Thai",
                Category = "Thai",
                Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nGarlic",
                Steps = "1. Soak rice noodles in warm water for 20 minutes, then drain.\n2. Press and cube tofu, then pan-fry until golden.\n3. Make the sauce: mix tamarind paste, fish sauce, and sugar.\n4. Stir-fry garlic, then add noodles and sauce.\n5. Toss with tofu, bean sprouts, and green onions.\n6. Serve with crushed peanuts and lime wedges.",
                Ratings = [4, 4, 3]
            },
            new Recipe
            {
                Id = 5,
                Title = "Beef Tacos",
                Category = "Mexican",
                Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa",
                Steps = "1. Brown ground beef in a skillet over medium-high heat.\n2. Add taco seasoning and a splash of water; simmer 5 minutes.\n3. Warm tortillas in a dry pan or microwave.\n4. Fill tortillas with seasoned beef.\n5. Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa.",
                Ratings = [4, 5, 4, 5]
            },
            new Recipe
            {
                Id = 6,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract",
                Steps = "1. Preheat oven to 425°F (220°C). Butter and flour two ramekins.\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick, then fold into chocolate mixture.\n4. Add flour and vanilla, stir until just combined.\n5. Pour into ramekins and bake 12–14 minutes.\n6. Invert onto plates and serve immediately.",
                Ratings = [5, 5, 5, 4, 5]
            },
            new Recipe
            {
                Id = 7,
                Title = "Miso Ramen",
                Category = "Japanese",
                Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onions\nNori\nCorn\nChashu pork (optional)",
                Steps = "1. Bring chicken broth to a simmer.\n2. Dissolve miso paste into the broth; add soy sauce and sesame oil.\n3. Cook ramen noodles according to package directions.\n4. Place noodles in a bowl and ladle broth over them.\n5. Top with halved soft-boiled egg, sliced green onions, nori, corn, and pork.",
                Ratings = [5, 4, 5]
            },
            new Recipe
            {
                Id = 8,
                Title = "Greek Salad",
                Category = "Mediterranean",
                Ingredients = "Cucumber\nTomatoes\nRed onion\nKalamata olives\nFeta cheese\nOlive oil\nRed wine vinegar\nOregano\nSalt",
                Steps = "1. Chop cucumber, tomatoes, and red onion into bite-sized pieces.\n2. Combine vegetables in a large bowl.\n3. Add olives and crumbled feta.\n4. Drizzle with olive oil and red wine vinegar.\n5. Season with oregano and salt. Toss gently and serve.",
                Ratings = [4, 3, 4]
            }
        ];
        _nextId = 9;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe is not null && stars is >= 1 and <= 5)
        {
            recipe.Ratings.Add(stars);
        }
    }

    public Recipe AddRecipe(string title, string category, string ingredients, string steps)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = title,
            Category = category,
            Ingredients = ingredients,
            Steps = steps
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

