@page "/"

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>RecipeShare — Home</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">🍳 Welcome to RecipeShare</h1>
    <p class="lead text-muted">Discover and share delicious recipes from around the world.</p>
</div>

<h2 class="mb-3">Browse by Category</h2>

<div class="row row-cols-1 row-cols-sm-2 row-cols-md-3 row-cols-lg-4 g-4">
    @foreach (var category in RecipeService.GetCategories())
    {
        <div class="col">
            <a href="category/@category" class="text-decoration-none">
                <div class="card h-100 shadow-sm border-0">
                    <div class="card-body text-center">
                        <span class="display-6">@GetCategoryEmoji(category)</span>
                        <h5 class="card-title mt-2">@category</h5>
                        <p class="text-muted small">
                            @RecipeService.GetByCategory(category).Count recipe(s)
                        </p>
                    </div>
                </div>
            </a>
        </div>
    }
</div>

@code {
    private static string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🥘",
        "Mexican" => "🌮",
        "Desserts" => "🍫",
        "Japanese" => "🍜",
        "Mediterranean" => "🥗",
        _ => "🍽️"
    };
}

